SET disabled_optimizers='outer_join_simplification';
CREATE TABLE t1(a INTEGER, b INTEGER, c INTEGER);
INSERT INTO t1 SELECT i % 7, CASE WHEN i % 3 = 0 THEN NULL ELSE i % 5 END, i FROM range(15) r(i);
CREATE TABLE t2(a INTEGER, b INTEGER, c INTEGER);
INSERT INTO t2 SELECT i % 7, CASE WHEN i % 3 = 0 THEN NULL ELSE i % 2 END, i FROM range(40) r(i);
CREATE TABLE t3(a INTEGER, b INTEGER, c INTEGER);
INSERT INTO t3 SELECT i % 5, CASE WHEN i % 3 = 0 THEN NULL ELSE i % 3 END, i FROM range(5) r(i);
CREATE TABLE t4(a INTEGER, b INTEGER, c INTEGER);
INSERT INTO t4 SELECT i % 6, CASE WHEN i % 3 = 0 THEN NULL ELSE i % 4 END, i FROM range(40) r(i);
SELECT * FROM (SELECT t4.a AS a1, t4.b AS b1, t3.a AS a2, t3.c AS c2 FROM t4 FULL OUTER JOIN t3 ON t4.a = t3.a WHERE t4.b <= 2 LIMIT 10) s1 UNION ALL SELECT * FROM (SELECT t4.a AS a1, t4.b AS b1, t3.a AS a2, t3.c AS c2 FROM t4 FULL OUTER JOIN t3 ON t4.a = t3.a WHERE t4.b <= 2 LIMIT 10) s2 ORDER BY ALL;

